<script setup lang="ts">
import { onBeforeUnmount, ref } from 'vue'
const placement=ref('end'),backdrop=ref(true),panel=ref<HTMLDialogElement|null>(null),opener=ref<HTMLButtonElement|null>(null),result=ref('Fictitious panel. Nothing is sent or saved.')
function show(){panel.value?.showModal()}
function close(){panel.value?.close();result.value='Sample panel dismissed. No record changed.'}
function restored(){opener.value?.focus()}
function outside(e:MouseEvent){if(!backdrop.value||e.target!==panel.value)return;const r=panel.value.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}
onBeforeUnmount(()=>panel.value?.close())
</script>
<template><section class="offcanvas-usage" aria-label="Offcanvas usage demonstration"><div class="settings"><label>Placement<select v-model="placement"><option>start</option><option>end</option><option>top</option><option>bottom</option></select></label><label><input v-model="backdrop" type="checkbox"> Dismiss on backdrop</label><button ref="opener" type="button" @click="show">Open sample panel</button></div><p role="status">{{result}}</p><dialog ref="panel" :class="placement" aria-labelledby="offcanvas-title" aria-describedby="offcanvas-copy" @keydown.tab.prevent="panel?.querySelector('button')?.focus()" @close="restored" @click="outside"><h2 id="offcanvas-title">Fictitious workspace details</h2><p id="offcanvas-copy">This {{placement}} panel keeps the page visible behind it, but the background is inert while this modal panel is open. No workspace is connected.</p><button autofocus type="button" @click="close">Close sample panel</button></dialog></section></template>
<style scoped>
.offcanvas-usage{padding:20px;border:1px solid var(--vp-c-divider);border-radius:12px;margin:20px 0}.settings{display:flex;gap:16px;align-items:center;flex-wrap:wrap}label{display:flex;gap:8px;align-items:center}button,select{min-height:44px;border:1px solid var(--vp-c-divider);border-radius:8px;padding:8px;background:var(--vp-c-bg-soft)}dialog{position:fixed;inset:0 0 0 auto;margin:0;width:min(400px,100vw);height:100dvh;max-width:100vw;max-height:100dvh;padding:24px;border:1px solid var(--vp-c-divider);background:var(--vp-c-bg);color:var(--vp-c-text-1);overflow:auto}dialog.start{inset:0 auto 0 0}dialog.top{inset:0 0 auto;width:100vw;height:auto;max-height:65dvh}dialog.bottom{inset:auto 0 0;width:100vw;height:auto;max-height:65dvh}dialog::backdrop{background:#0009}dialog[open]{animation:panel-arrival 180ms ease-out}h2{margin-top:0!important;border:0!important}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:3px}@keyframes panel-arrival{from{opacity:.5;translate:8px 0}to{opacity:1;translate:0 0}}dialog.start[open]{animation-name:from-start}dialog.top[open]{animation-name:from-top}dialog.bottom[open]{animation-name:from-bottom}@keyframes from-start{from{opacity:.5;translate:-8px 0}to{opacity:1;translate:0 0}}@keyframes from-top{from{opacity:.5;translate:0 -8px}to{opacity:1;translate:0 0}}@keyframes from-bottom{from{opacity:.5;translate:0 8px}to{opacity:1;translate:0 0}}@media(prefers-reduced-motion:reduce){dialog[open]{animation:none;translate:none}}
</style>
